import {Model,COLORS,part,dims,starter,validateProject,LIMIT} from './model.js';
import {Workshop} from './scene.js';
import {HUD} from './hud.js';
const STORAGE='bricklab.project.v1',SETTINGS='bricklab.settings.v1',model=new Model();let restored=false,saveTimer;
// Workshop settings are device preferences, kept apart from the project so exported files never carry them.
const settings={gravity:true,sound:true};try{const raw=JSON.parse(localStorage.getItem(SETTINGS)||'{}');for(const key of Object.keys(settings))if(typeof raw[key]==='boolean')settings[key]=raw[key];}catch(e){console.warn('[Bricklab] Saved settings could not be read',e);}
model.gravity=settings.gravity;
try{const raw=localStorage.getItem(STORAGE);if(raw){Object.assign(model,validateProject(JSON.parse(raw),{gravity:model.gravity}));restored=true;}}catch(e){console.warn('[Bricklab] Saved project could not be restored',e);}
if(!restored)Object.assign(model,validateProject(starter()));
const state={model,part:'b24',color:COLORS[0][1],category:'Bricks',rotation:0,tool:'build',selected:null,modal:null,saved:restored?'Restored on this device':'Autosave on this device',backend:'',toast:restored?'Welcome back. Your build is right here.':'Make yourself at home. Add your first brick.',toastUntil:performance.now()+5000,sound:settings.sound};
const canvas=document.querySelector('#hud'), hud=new HUD(canvas,state,action);hud.draw();const world=new Workshop();
try{await world.init(document.querySelector('#world'),canvas,model);state.backend=world.backend;hud.dirty=true;console.info('[Bricklab] Ready',{backend:world.backend,pieces:model.bricks.length,capacity:LIMIT});}catch(err){console.error('[Bricklab] Renderer initialization failed',err);state.toast='3D could not start. Enable WebGL 2, then reload.';state.toastUntil=Infinity;hud.dirty=true;hud.draw();throw err;}
let candidate=null,moveId=null,heightOffset=0,lastPointer=null,viewIndex=0,audioContext;
function toast(message){state.toast=message;state.toastUntil=performance.now()+3400;hud.dirty=true;setTimeout(()=>hud.dirty=true,3500);}
function clickSound(){if(!state.sound)return;try{audioContext??=new AudioContext();audioContext.resume();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.setValueAtTime(650,audioContext.currentTime);osc.frequency.exponentialRampToValueAtTime(290,audioContext.currentTime+.06);gain.gain.setValueAtTime(.035,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.075);osc.connect(gain).connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+.08);}catch{}}
function saveSettings(){settings.gravity=model.gravity;settings.sound=state.sound;try{localStorage.setItem(SETTINGS,JSON.stringify(settings));}catch(err){console.warn('[Bricklab] Settings could not be saved',err);}}
function autosave(){try{localStorage.setItem(STORAGE,JSON.stringify(model.serialize()));state.saved='Saved on this device';}catch(err){state.saved='Save failed — export your work';toast('Device storage is full. Export your project to keep it.');console.warn('[Bricklab] Autosave failed',err);}hud.dirty=true;}
// Undo and redo can flip gravity back, so the saved setting follows the model.
model.onChange(()=>{if(model.gravity!==settings.gravity)saveSettings();if(model.fallen)toast(model.fallen===1?'1 piece fell':model.fallen+' pieces fell');state.saved='Saving…';clearTimeout(saveTimer);saveTimer=setTimeout(autosave,250);if(state.selected&&!model.bricks.some(b=>b.id===state.selected))state.selected=null;world.select(state.selected);hud.dirty=true;});
window.addEventListener('pagehide',()=>{clearTimeout(saveTimer);autosave();});
function select(id){state.selected=id;world.select(id);hud.dirty=true;}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function safeName(){return model.name.replace(/[^a-z0-9_-]/gi,'-').toLowerCase();}
async function photo(){state.modal=null;world.preview(null);const selected=state.selected;world.select(null);world.renderer.render(world.scene,world.camera);document.querySelector('#world').toBlob(blob=>{if(blob){download(blob,safeName()+'.png');toast('Snapshot downloaded');}else toast('Image export failed. Please try again.');world.select(selected);},'image/png');hud.dirty=true;}
function action(id){
 if(id.startsWith('part:')){state.part=id.slice(5);state.tool='build';moveId=null;heightOffset=0;select(null);}
 else if(id.startsWith('color:')){state.color=id.slice(6);if(state.tool==='select'&&state.selected){model.update(state.selected,{color:state.color});clickSound();}}
 else if(id.startsWith('category:'))state.category=id.slice(9);
 else if(id.startsWith('tool:')){state.tool=id.slice(5);moveId=null;heightOffset=0;world.preview(null);}
 else if(id==='rotate'){if(state.selected&&state.tool!=='build'&&!moveId){const b=model.bricks.find(b=>b.id===state.selected);const err=model.update(b.id,{r:(b.r+1)%4});if(err)toast(err);}else{state.rotation=(state.rotation+1)%4;if(moveId){const b=model.bricks.find(b=>b.id===moveId);state.part=b.part;}updatePreview();}}
 else if(id==='undo'||id==='redo'){if(model[id]())toast(id==='undo'?'Undone':'Redone');moveId=null;world.preview(null);}
 else if(id==='home')world.home();else if(id==='plus')world.zoom(.85);else if(id==='minus')world.zoom(1.15);
 else if(id==='grid'){world.grid.visible=!world.grid.visible;world.dirty=true;}
 else if(id==='view'){viewIndex=(viewIndex+1)%3;world.home(['iso','top','front'][viewIndex]);toast(['Perspective view','Top view','Front view'][viewIndex]);}
 else if(['projects','export','help','settings'].includes(id)){state.modal=id;world.preview(null);}
 else if(id==='close'){state.modal=null;}
 else if(id==='sound'){state.sound=!state.sound;saveSettings();toast(state.sound?'Brick sounds on':'Brick sounds off');}
 else if(id==='gravity'){model.setGravity(!model.gravity);moveId=null;world.preview(null);toast(!model.gravity?'Gravity off. Pieces stay where you put them.':model.fallen===1?'Gravity on. 1 piece fell. Undo to bring it back.':model.fallen?`Gravity on. ${model.fallen} pieces fell. Undo to bring them back.`:'Gravity on');}
 else if(id.startsWith('starter:')){model.replace(starter(id.slice(8)));state.modal=null;moveId=null;heightOffset=0;select(null);world.home();toast(id==='starter:blank'?'A fresh plate. What will you build?':'Ready for your own twist.');}
 else if(id==='download'){download(new Blob([JSON.stringify(model.serialize(),null,2)],{type:'application/json'}),safeName()+'.bricklab');toast('Project downloaded');}
 else if(id==='photo')photo();
 else if(id==='import')document.querySelector('#file').click();
 else if(id==='delete'&&state.selected){model.remove(state.selected);select(null);clickSound();}
 else if(id==='duplicate'&&state.selected){const b=model.bricks.find(b=>b.id===state.selected);state.part=b.part;state.color=b.color;state.rotation=b.r;state.category=part(b.part).group;state.tool='build';select(null);toast('Copy ready. Click to place it.');}
 else if((id==='lift'||id==='lower')&&state.selected){const b=model.bricks.find(b=>b.id===state.selected),err=model.update(b.id,{y:b.y+(id==='lift'?1:-1)});if(err)toast(err);}
 hud.dirty=true;world.dirty=true;
}
document.querySelector('#file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error('Project file exceeds 2 MB');const data=JSON.parse(await file.text());model.replace(data);state.modal=null;select(null);moveId=null;world.home();toast('Project opened — '+model.bricks.length+' pieces');}catch(err){toast('Could not open project: '+err.message);}e.target.value='';});
function makeCandidate(x,y){const hit=world.hit(x,y);if(!hit)return null;let b=moveId?model.bricks.find(b=>b.id===moveId):null;const p=part(b?.part||state.part),r=state.rotation,d=r%2?{w:p.d,d:p.w}:p;let yLevel=0;if(hit.id&&hit.id!==moveId){const under=model.bricks.find(b=>b.id===hit.id);yLevel=under.y+part(under.part).h;}return {part:p.id,color:b?.color||state.color,r,x:Math.floor(hit.point.x-d.w/2+.5),z:Math.floor(hit.point.z-d.d/2+.5),y:Math.max(0,yLevel+heightOffset)};}
function updatePreview(){if(!lastPointer||state.modal||hud.hit(lastPointer.x,lastPointer.y)||!(state.tool==='build'||moveId)){candidate=null;world.preview(null);return;}candidate=makeCandidate(lastPointer.x,lastPointer.y);world.preview(candidate,candidate&&!model.valid(candidate,moveId));}
let start=null,activePointers=new Set(),multiGesture=false;
canvas.addEventListener('pointerdown',e=>{canvas.focus({preventScroll:true});activePointers.add(e.pointerId);if(activePointers.size>1)multiGesture=true;const zone=hud.hit(e.clientX,e.clientY);world.controls.enabled=!zone&&!state.modal;start={x:e.clientX,y:e.clientY,zone:zone?.id,button:e.button};if(zone||state.modal)e.stopImmediatePropagation();},true);
canvas.addEventListener('pointermove',e=>{lastPointer={x:e.clientX,y:e.clientY};const z=hud.hit(e.clientX,e.clientY);if(hud.hover!==z?.id){hud.hover=z?.id;hud.dirty=true;}canvas.style.cursor=z?'pointer':state.tool==='build'?'crosshair':'grab';if(start&&Math.hypot(e.clientX-start.x,e.clientY-start.y)>6){world.preview(null);return;}updatePreview();});
canvas.addEventListener('pointerup',e=>{activePointers.delete(e.pointerId);if(!start){if(!activePointers.size)multiGesture=false;return;}const moved=Math.hypot(e.clientX-start.x,e.clientY-start.y)>6,zone=hud.hit(e.clientX,e.clientY);if(!moved&&!multiGesture&&start.zone&&zone?.id===start.zone&&!zone.disabled)action(start.zone);else if(!moved&&!multiGesture&&!start.zone&&!zone&&!state.modal&&start.button===0){const hit=world.hit(e.clientX,e.clientY);lastPointer={x:e.clientX,y:e.clientY};if(state.tool==='build'||moveId){candidate=makeCandidate(e.clientX,e.clientY);if(candidate){const err=moveId?model.update(moveId,candidate):model.add(candidate);if(err)toast(err);else{clickSound();if(moveId){moveId=null;state.tool='select';world.preview(null);toast('Brick moved');}else{if(model.bricks.length%25===0)toast(model.bricks.length+' pieces. Looking good!');updatePreview();}}}}else if(hit?.id){select(hit.id);if(state.tool==='erase'){model.remove(hit.id);select(null);clickSound();}else if(state.tool==='paint'){model.update(hit.id,{color:state.color});clickSound();}else if(state.tool==='move'){moveId=hit.id;const b=model.bricks.find(b=>b.id===moveId);state.rotation=b.r;heightOffset=0;toast('Choose a new position. Esc to cancel.');}else{const b=model.bricks.find(b=>b.id===hit.id);state.part=b.part;state.color=b.color;state.rotation=b.r;state.category=part(b.part).group;}}else select(null);}start=null;if(!activePointers.size)multiGesture=false;world.controls.enabled=true;hud.dirty=true;},true);
canvas.addEventListener('pointercancel',()=>{activePointers.clear();multiGesture=false;start=null;world.controls.enabled=true;});
canvas.addEventListener('pointerleave',()=>{if(!start)world.preview(null);});canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('wheel',e=>{if(hud.hit(e.clientX,e.clientY)||state.modal){e.stopImmediatePropagation();e.preventDefault();}},{capture:true,passive:false});
window.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();hud.focus=(hud.focus+(e.shiftKey?-1:1)+hud.zones.length)%hud.zones.length;hud.dirty=true;return;}if((e.key==='Enter'||e.key===' ')&&hud.focus>=0){e.preventDefault();const z=hud.zones[hud.focus];if(z&&!z.disabled)action(z.id);return;}hud.focus=-1;const key=e.key.toLowerCase();if((e.ctrlKey||e.metaKey)&&key==='z'){e.preventDefault();action(e.shiftKey?'redo':'undo');return;}if((e.ctrlKey||e.metaKey)&&key==='s'){e.preventDefault();action('download');return;}if(key==='escape'){state.modal=null;moveId=null;world.preview(null);select(null);hud.dirty=true;return;}if(state.modal)return;const keys={b:'tool:build',v:'tool:select',m:'tool:move',p:'tool:paint',x:'tool:erase',r:'rotate',d:'duplicate',delete:'delete',backspace:'delete',f:'home',h:'help'};if(keys[key]){e.preventDefault();action(keys[key]);}if(key==='t'){world.home('top');toast('Top view');}if(key==='['||key===']'){e.preventDefault();if(state.selected&&state.tool!=='build'&&!moveId)action(key===']'?'lift':'lower');else{heightOffset+=key===']'?1:-1;updatePreview();toast('Placement offset: '+heightOffset+' plates');}}});
window.addEventListener('resize',()=>{world.resize();hud.resize();});
// Read-only diagnostics describe the current visible workshop; no test-only mutations.
window.bricklabDiagnostics=()=>({backend:world.backend,pieces:model.bricks.length,revision:model.revision,drawCalls:world.renderer.info.render.drawCalls,triangles:world.renderer.info.render.triangles,frames:world.frames,lastSubmissionMs:Number(world.frameMs.toFixed(2)),selected:state.selected,tool:state.tool,history:{undo:model.past.length,redo:model.future.length},project:model.serialize()});
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const register=t=>{try{Promise.resolve(context.registerTool(t,{signal:lifecycle.signal})).catch(e=>console.warn('[Bricklab] Tool registration unavailable',e));}catch(e){console.warn('[Bricklab] Tool registration unavailable',e);}};register({name:'inspect_brick_build',description:'Read the current brick project, the remaining capacity and whether gravity is on.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({project:model.serialize(),capacity:LIMIT,gravity:model.gravity})});register({name:'add_build_bricks',description:'Place up to 100 bricks atomically on the current build plate. Coordinates are integer studs, height is in plates. When gravity is on (the default, see inspect_brick_build), every brick must be held up: resting on the plate or another piece, or hanging beneath a held piece by its own studs. Tiles and slopes have smooth tops, so nothing can hang beneath them. Bricks in the same batch may hold each other up.',inputSchema:{type:'object',properties:{bricks:{type:'array',minItems:1,maxItems:100,items:{type:'object',properties:{part:{type:'string'},color:{type:'string'},x:{type:'integer'},y:{type:'integer'},z:{type:'integer'},r:{type:'integer',minimum:0,maximum:3}},required:['part','color','x','y','z','r'],additionalProperties:false}}},required:['bricks'],additionalProperties:false},execute:input=>{if(!Array.isArray(input?.bricks)||input.bricks.length<1||input.bricks.length>100)throw Error('Supply 1–100 bricks');const err=model.addMany(input.bricks);if(err)throw Error(err);hud.dirty=true;hud.draw();return {pieces:model.bricks.length};}});window.addEventListener('pagehide',()=>lifecycle.abort());}
let lastHud=0;function loop(t){world.tick(t);if(t-lastHud>1000){lastHud=t;if(state.toast&&t>state.toastUntil){state.toast='';hud.dirty=true;}}hud.draw();requestAnimationFrame(loop);}requestAnimationFrame(loop);
